        for c in range(w):
            if grid[r][c] == 0 or comp_id[r][c] != -1:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            comp_id[r][c] = len(comps)
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and comp_id[nx][ny] == -1:
                        comp_id[nx][ny] = len(comps)
                        q.append((nx, ny))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            r0, r1 = min(rs), max(rs)
            c0, c1 = min(cs), max(cs)
            hh, ww = r1 - r0 + 1, c1 - c0 + 1
            area = len(cells)
            rectangular = (area == hh * ww)
            comps.append({
                "id": len(comps),
                "color": color,
                "cells": cells,
                "set": set(cells),
                "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                "h": hh, "w": ww,
                "area": area,
                "rect": rectangular,
            })

    # Build adjacency between components of different colors
    adj = defaultdict(set)
    for r in range(h):
        for c in range(w):
            a = comp_id[r][c]
            if a == -1:
                continue
            for dr, dc in ((1, 0), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    b = comp_id[nr][nc]
                    if b != -1 and b != a:
                        adj[a].add(b)
                        adj[b].add(a)

