            exemplar_by_marker[marker_color] = {
                "pattern_id": p_id,
                "marker_id": m_id,
                "offsets": offsets,
            }

    # Apply each exemplar to rectangular target components adjacent to same marker color
    for marker_color, ex in exemplar_by_marker.items():
        exemplar_pattern_id = ex["pattern_id"]
        exemplar_marker_id = ex["marker_id"]
        offsets = ex["offsets"]

        for m in comps:
